// Code node do n8n — converte o CSV embutido em itens estruturados
const csv = $json.data; // campo "data" do payload recebido

const linhas = csv.split('\n').filter(linha => linha.trim() !== '');
const [cabecalho, ...dados] = linhas;
const colunas = cabecalho.split(',');

const registros = dados.map(linha => {
  const valores = linha.split(',');
  const obj = {};
  colunas.forEach((coluna, i) => {
    obj[coluna.trim()] = (valores[i] ?? '').trim();
  });
  return obj;
});
let investimentos = registros.map(registro => (registro));
return {investimentos}

// Code node do n8n — recomendação de investimento + mensagem aleatória

// 1) Normaliza "R$ 12.500,00" -> 12500
const parseSaldo = (valor) => {
  if (typeof valor !== 'string') return Number(valor) || 0;
  return Number(valor.replace(/[^\d,]/g, '').replace(/\./g, '').replace(',', '.')) || 0;
};

// 2) Score de rentabilidade para ordenar as opções ("Variável" fica por último)
const scoreRentabilidade = (rent) => {
  if (typeof rent !== 'string') return -1;
  const match = rent.match(/(\d+(?:[.,]\d+)?)/);
  let score = match ? parseFloat(match[1].replace(',', '.')) : -1;
  if (rent.includes('IPCA+')) score += 5; // bônus por retorno real (IPCA + 6%)
  return score;
};

// 3) Templates de mensagem (4 variações, sorteadas por cliente)
const templates = [
  (c, r) => `Olá, ${c.nome}! Com base no seu perfil ${c.perfil}, recomendamos o ${r.produto} (rentabilidade de ${r.rentabilidade}). É uma ótima oportunidade para o seu momento. Quer conversar com um especialista?`,
  (c, r) => `${c.nome}, pensando no seu objetivo de investimento, o ${r.produto} se destaca com ${r.rentabilidade}. Seu saldo atual permite começar hoje mesmo. Posso te ajudar com isso?`,
  (c, r) => `Oi, ${c.nome}! Para o seu perfil ${c.perfil}, o ${r.produto} é uma excelente escolha (${r.rentabilidade}). Vamos agendar uma conversa para detalhar?`,
  (c, r) => `${c.nome}, uma oportunidade para você: ${r.produto} com rentabilidade de ${r.rentabilidade}. Perfeito para o perfil ${c.perfil}. Responda se quiser saber mais!`
];

const clientes = $json.body?.clientes ?? $json.clientes ?? [];
const investimentos = $json.investimentos ?? [];

return clientes.map(cliente => {
  const saldo = parseSaldo(cliente.saldo);
  const doPerfil = investimentos.filter(inv => inv.perfil === cliente.perfil);

  // Só produtos cujo ticket mínimo o saldo do cliente cobre, ordenados por rentabilidade
  const elegiveis = doPerfil
    .map(inv => ({ ...inv, minimoNum: Number(inv.minimo) || 0 }))
    .filter(inv => saldo >= inv.minimoNum)
    .sort((a, b) => scoreRentabilidade(b.rentabilidade) - scoreRentabilidade(a.rentabilidade));

  // Fallback: se nada couber no saldo, recomenda a opção de menor aporte do perfil
  const recomendacao = elegiveis[0] ??
    [...doPerfil].sort((a, b) => (Number(a.minimo) || 0) - (Number(b.minimo) || 0))[0] ??
    { produto: 'Produto não disponível', minimo: '-', rentabilidade: '-' };

  const mensagem = templates[Math.floor(Math.random() * templates.length)](cliente, recomendacao);

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      saldoNum: saldo,
      produto: recomendacao.produto,
      minimo: recomendacao.minimo,
      rentabilidade: recomendacao.rentabilidade,
      elegivel: elegiveis.length > 0,
      mensagem
    }
  };
});
